def max_sum(arr, forbidden_idx):
    max_sum = 0

    # Calculate the max sum without the forbidden index
    for i in range(len(arr)):
        if i == forbidden_idx:
            continue
        max_sum += arr[i]

    # Calculate the max sum with the forbidden index
    for i in range(len(arr)):
        if i == forbidden_idx:
            continue
        new_sum = max_sum - arr[i] + arr[forbidden_idx]
        if new_sum > max_sum:
            max_sum = new_sum

    return max_sum

