def getNumTrees(n, k):
	num = 0
	L = []
	par = []
	levels = []
	children = []

	p = n-1
	q = 0

	for i in range(n):
		L.append(i)
		par.append(i)
		levels.append(i+1)
		children.append(0)

	while (p > 0):
		for i in range(n):
			children[i] = 0
		for i in range(n):
			children[par[i]] += 1

		if max(children) <= k:
			num += 1

		p = 0
		for i in range(n-1, -1, -1):
			if L[i] > 1:
				p = i
				break

		if p == 0:
			break

		for i in range(p-1, -1, -1):
			if L[i] == L[p] - 1:
				q = i
				break

		for i in range(p, n):
			L[i] = L[i-p+q]

		for i in range(1, n):
			x = L[i]
			par[i] = levels[x-1]
